draw:
var F = "12px ui-sans-serif, system-ui, sans-serif";
var d = p.d;
var v = p.v;
var m = p.m;
var ox = W * 0.16, oy = H * 0.78;
var pxPerM = Math.min(W / 9.0, H / 4.5);
var lineY = oy - d * pxPerM;

ctx.lineWidth = 1;
ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(W * 0.03, lineY); ctx.lineTo(W * 0.97, lineY); ctx.stroke();
ctx.setLineDash([]);

var cycle = 4.0;
var frac = (t % cycle) / cycle;
var bx = W * 0.06 + frac * W * 0.88;

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(bx, lineY); ctx.stroke();

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ox, lineY); ctx.stroke();
ctx.beginPath();
ctx.moveTo(ox - 4, lineY + 8); ctx.lineTo(ox, lineY); ctx.lineTo(ox + 4, lineY + 8);
ctx.stroke();

ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(bx, lineY, 7, 0, Math.PI * 2); ctx.fill();

ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
var av = 34;
ctx.beginPath();
ctx.moveTo(bx + 9, lineY); ctx.lineTo(bx + 9 + av, lineY);
ctx.moveTo(bx + 9 + av, lineY); ctx.lineTo(bx + 9 + av - 6, lineY - 4);
ctx.moveTo(bx + 9 + av, lineY); ctx.lineTo(bx + 9 + av - 6, lineY + 4);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(ox, oy, 3.5, 0, Math.PI * 2); ctx.fill();

ctx.font = F;
ctx.textAlign = "left";
ctx.fillStyle = C.ink;
ctx.fillText("O", ox + 7, oy + 5);
ctx.fillText("v = " + v.toFixed(1) + " m/s", bx + 14 + av, lineY - 6);
ctx.fillText("m = " + m.toFixed(2) + " kg", bx - 14, lineY - 14);
ctx.fillStyle = C.accent;
ctx.fillText("r-perp = " + d.toFixed(1) + " m", ox + 8, (oy + lineY) / 2);
ctx.fillStyle = C.rule;
ctx.fillText("r", (ox + bx) / 2, (oy + lineY) / 2 - 6);
ctx.fillStyle = C.faint;
ctx.fillText("line of motion", W * 0.72, lineY - 10);

out.note = "L = m v r-perp = " + (m * v * d).toFixed(2) + " kg m^2/s about O, constant as the ball moves";

var F = "12px ui-sans-serif, system-ui, sans-serif";
var Icore = p.Icore, marm = p.marm, r = p.r, L = p.L;
var I = Icore + 2 * marm * r * r;
var w = L / I;
var KE = 0.5 * L * w;

var cx = W * 0.5, cy = H * 0.55;
var pxPerM = Math.min(W * 0.40, H * 0.36) / 1.2;
var ang = w * t * 0.35;

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.arc(cx, cy, r * pxPerM, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);

var coreR = Math.max(8, 0.22 * pxPerM);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(cx, cy, coreR, 0, Math.PI * 2); ctx.fill();

var i;
for (i = 0; i < 2; i++) {
  var a = ang + i * Math.PI;
  var ax = cx + Math.cos(a) * r * pxPerM;
  var ay = cy + Math.sin(a) * r * pxPerM;
  ctx.strokeStyle = C.rule;
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ax, ay); ctx.stroke();
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(ax, ay, Math.max(5, 4 + marm * 3), 0, Math.PI * 2); ctx.fill();
}

var a0 = ang;
var hx = cx + Math.cos(a0) * r * pxPerM;
var hy = cy + Math.sin(a0) * r * pxPerM;
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(cx + Math.cos(a0) * r * pxPerM * 0.55, cy + Math.sin(a0) * r * pxPerM * 0.55);
ctx.stroke();

ctx.font = F;
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("r = " + r.toFixed(2) + " m", cx, cy - coreR - 8);
ctx.textAlign = "left";
ctx.fillStyle = C.accent;
ctx.fillText("arm mass " + marm.toFixed(1) + " kg", W * 0.03, H * 0.12);
ctx.fillStyle = C.ink;
ctx.fillText("I = " + I.toFixed(2) + " kg m^2", W * 0.03, H * 0.12 + 15);
ctx.fillText("omega = " + w.toFixed(2) + " rad/s", W * 0.03, H * 0.12 + 30);
ctx.fillStyle = C.faint;
ctx.textAlign = "right";
ctx.fillText("L held fixed at " + L.toFixed(1) + " kg m^2/s", W * 0.97, H * 0.12);

out.note = "I = " + I.toFixed(3) + " kg m^2, omega = L/I = " + w.toFixed(2) + " rad/s, K = L^2/2I = " + KE.toFixed(2) + " J";

var F = "12px ui-sans-serif, system-ui, sans-serif";
var M = p.M, Lr = p.Lrod, mb = p.mb, vb = p.vb, f = p.f;

var dCen = Math.abs(Lr / 2 - f * Lr);
var Irod = M * Lr * Lr / 12 + M * dCen * dCen;
var rArm = Lr * (1 - f);
var w = mb * vb * rArm / (Irod + mb * rArm * rArm);

var pxPerM = Math.min(W * 0.72 / Lr, H * 0.30 / (Lr * 0.5));
var px = W * 0.5 - (0.5 - f) * Lr * pxPerM;
var py = H * 0.48;

var tApproach = 1.1, tSpin = 3.0, cyc = tApproach + tSpin;
var now = t % cyc;
var hitX = px + rArm * pxPerM;

var ang = 0;
if (now >= tApproach) ang = w * (now - tApproach) * 0.4;

ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(px - Lr * f * pxPerM - 10, py); ctx.lineTo(px + rArm * pxPerM + 10, py); ctx.stroke();
ctx.setLineDash([]);

var e1 = -f * Lr * pxPerM, e2 = rArm * pxPerM;
var ca = Math.cos(ang), sa = Math.sin(ang);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 6;
ctx.lineCap = "round";
ctx.beginPath();
ctx.moveTo(px + e1 * ca, py + e1 * sa);
ctx.lineTo(px + e2 * ca, py + e2 * sa);
ctx.stroke();
ctx.lineCap = "butt";

if (now < tApproach) {
  var frac = now / tApproach;
  var by = py + (1 - frac) * H * 0.34 + 14;
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(hitX, by, 4.5, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(hitX, by - 6); ctx.lineTo(hitX, by - 20);
  ctx.moveTo(hitX, by - 20); ctx.lineTo(hitX - 4, by - 14);
  ctx.moveTo(hitX, by - 20); ctx.lineTo(hitX + 4, by - 14);
  ctx.stroke();
  ctx.font = F;
  ctx.fillStyle = C.accent;
  ctx.textAlign = "center";
  ctx.fillText("v = " + vb.toFixed(0) + " m/s", hitX, by + 22);
} else {
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(px + e2 * ca, py + e2 * sa, 4.5, 0, Math.PI * 2); ctx.fill();
}

ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px, py, 4, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.arc(px, py, 8, 0, Math.PI * 2); ctx.stroke();

ctx.font = F;
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("pivot", px, py + 24);
ctx.textAlign = "left";
ctx.fillText("lever arm r = " + rArm.toFixed(2) + " m", W * 0.03, H * 0.13);
ctx.fillText("I about pivot = " + (Irod + mb * rArm * rArm).toFixed(3) + " kg m^2", W * 0.03, H * 0.13 + 15);
ctx.textAlign = "right";
ctx.fillStyle = C.faint;
ctx.fillText("rod M = " + M.toFixed(1) + " kg, L = " + Lr.toFixed(1) + " m", W * 0.97, H * 0.13);
ctx.fillText("bullet m = " + mb.toFixed(3) + " kg", W * 0.97, H * 0.13 + 15);

out.note = "L before = m v r = " + (mb * vb * rArm).toFixed(3) + " kg m^2/s, so omega after = " + w.toFixed(2) + " rad/s";
